1	import { useState, useMemo, useEffect } from "react";
2	import { Link } from "wouter";
3	import { ChevronLeft, ChevronRight, ChevronDown, Check } from "lucide-react";
4	import { useQueryClient } from "@tanstack/react-query";
5	import {
6	  useGetOverdueItems,
7	  useUpdateTask,
8	  useUpdateEblast,
9	  getGetOverdueItemsQueryKey,
10	  getGetDashboardSummaryQueryKey,
11	} from "@workspace/api-client-react";
12	import { Button } from "@/components/ui/button";
13	import { Skeleton } from "@/components/ui/skeleton";
14	import { Textarea } from "@/components/ui/textarea";
15	import { formatDate } from "@/lib/date-utils";
16	
17	const CATEGORY_COLORS: Record<string, string> = {
18	  "Show Bucket":        "bg-blue-500/15 text-blue-400 border-blue-500/30",
19	  "Fire Marshal":       "bg-red-500/15 text-red-400 border-red-500/30",
20	  "ID Sign":            "bg-purple-500/15 text-purple-400 border-purple-500/30",
21	  "Warehouse Manifest": "bg-cyan-500/15 text-cyan-400 border-cyan-500/30",
22	  "Vehicle Spotting":   "bg-amber-500/15 text-amber-400 border-amber-500/30",
23	  eblast:               "bg-pink-500/15 text-pink-400 border-pink-500/30",
24	};
25	
26	function chipClass(type: string, category: string | null | undefined) {
27	  if (type === "eblast") return CATEGORY_COLORS["eblast"];
28	  return CATEGORY_COLORS[category ?? ""] ?? "bg-slate-500/15 text-slate-400 border-slate-500/30";
29	}
30	
31	function itemKey(type: string, id: number) {
32	  return `${type}-${id}`;
33	}
34	
35	export function DashboardTaskSlider() {
36	  const queryClient = useQueryClient();
37	  const { data: rawItems, isLoading } = useGetOverdueItems();
38	  const updateTask = useUpdateTask();
39	  const updateEblast = useUpdateEblast();
40	
41	  const [index, setIndex] = useState(0);
42	  // Per-item note drafts keyed by "type-id"
43	  const [noteDrafts, setNoteDrafts] = useState<Record<string, string>>({});
44	  // Track which items have a "Saved" flash
45	  const [savedFlash, setSavedFlash] = useState<Record<string, boolean>>({});
46	  // Track items being completed (to fade them out before refetch)
47	  const [completing, setCompleting] = useState<Record<string, boolean>>({});
48	  // Which item's note is expanded
49	  const [noteOpen, setNoteOpen] = useState<Record<string, boolean>>({});
50	
51	  const items = useMemo(() => {
52	    if (!rawItems) return [];
53	    const dueToday = rawItems.filter(i => i.daysOverdue === 0);
54	    const overdue = rawItems
55	      .filter(i => i.daysOverdue > 0)
56	      .sort((a, b) => b.daysOverdue - a.daysOverdue);
57	    return [...dueToday, ...overdue];
58	  }, [rawItems]);
59	
60	  // Seed note drafts from fresh API data when items load
61	  useEffect(() => {
62	    if (!items.length) return;
63	    setNoteDrafts(prev => {
64	      const next = { ...prev };
65	      for (const item of items) {
66	        const k = itemKey(item.type, item.id);
67	        if (!(k in next)) next[k] = item.notes ?? "";
68	      }
69	      return next;
70	    });
71	  }, [items]);
72	
73	  const invalidate = () => {
74	    queryClient.invalidateQueries({ queryKey: getGetOverdueItemsQueryKey() });
75	    queryClient.invalidateQueries({ queryKey: getGetDashboardSummaryQueryKey() });
76	  };
77	
78	  if (isLoading) return <Skeleton className="w-full h-40 rounded-lg" />;
79	  if (items.length === 0) return null;
80	
81	  const safeIndex = Math.min(index, items.length - 1);
82	  const item = items[safeIndex];
83	  const isToday = item.daysOverdue === 0;
84	  const total = items.length;
85	  const key = itemKey(item.type, item.id);
86	  const currentNote = noteDrafts[key] ?? item.notes ?? "";
87	  const isCompleting = completing[key] ?? false;
88	
89	  const prev = () => setIndex(i => Math.max(0, i - 1));
90	  const next = () => setIndex(i => Math.min(total - 1, i + 1));
91	
92	  const saveNote = () => {
93	    const draft = currentNote;
94	    const original = item.notes ?? "";
95	    if (draft === original) return;
96	
97	    if (item.type === "task") {
98	      updateTask.mutate(
99	        { showId: item.showId, taskId: item.id, data: { notes: draft || null } },
100	        { onSuccess: () => {
101	            setSavedFlash(p => ({ ...p, [key]: true }));
102	            setTimeout(() => setSavedFlash(p => ({ ...p, [key]: false })), 1500);
103	            invalidate();
104	          }
105	        }
106	      );
107	    } else {
108	      updateEblast.mutate(
109	        { showId: item.showId, eblastId: item.id, data: { notes: draft || null } },
110	        { onSuccess: () => {
111	            setSavedFlash(p => ({ ...p, [key]: true }));
112	            setTimeout(() => setSavedFlash(p => ({ ...p, [key]: false })), 1500);
113	            invalidate();
114	          }
115	        }
116	      );
117	    }
118	  };
119	
120	  const markComplete = () => {
121	    setCompleting(p => ({ ...p, [key]: true }));
122	    const now = new Date().toISOString();
123	
124	    if (item.type === "task") {
125	      updateTask.mutate(
126	        { showId: item.showId, taskId: item.id, data: { completed: true, completedAt: now } },
127	        { onSuccess: () => {
128	            invalidate();
129	            // Move index back if we're at the end
130	            setIndex(i => Math.max(0, Math.min(i, total - 2)));
131	            setCompleting(p => ({ ...p, [key]: false }));
132	          },
133	          onError: () => setCompleting(p => ({ ...p, [key]: false })),
134	        }
135	      );
136	    } else {
137	      updateEblast.mutate(
138	        { showId: item.showId, eblastId: item.id, data: { sent: true, sentAt: now } },
139	        { onSuccess: () => {
140	            invalidate();
141	            setIndex(i => Math.max(0, Math.min(i, total - 2)));
142	            setCompleting(p => ({ ...p, [key]: false }));
143	          },
144	          onError: () => setCompleting(p => ({ ...p, [key]: false })),
145	        }
146	      );
147	    }
148	  };
149	
150	  const showTab = item.type === "eblast" ? "eblasts" : "tasks";
151	  const completionLabel = item.type === "eblast" ? "Mark Sent" : "Mark Complete";
152	  const isNoteOpen = noteOpen[key] ?? false;
153	
154	  const openNote = () => setNoteOpen(p => ({ ...p, [key]: true }));
155	  const closeNote = () => {
156	    saveNote();
157	    setNoteOpen(p => ({ ...p, [key]: false }));
158	  };
159	
160	  return (
161	    <div
162	      className={`rounded-lg border p-5 flex flex-col gap-4 transition-opacity duration-300 ${isCompleting ? "opacity-40 pointer-events-none" : ""} ${isToday ? "bg-amber-500/5 border-amber-500/20" : "bg-red-500/5 border-red-500/20"}`}
163	    >
164	      {/* Header: urgency label + counter + arrows */}
165	      <div className="flex items-center justify-between gap-3">
166	        <span className={`text-xs font-bold uppercase tracking-widest ${isToday ? "text-amber-400" : "text-red-400"}`}>
167	          {isToday ? "Due Today" : `${item.daysOverdue} ${item.daysOverdue === 1 ? "day" : "days"} overdue`}
168	        </span>
169	        <div className="flex items-center gap-2">
170	          <span className="text-xs text-muted-foreground tabular-nums">{safeIndex + 1} / {total}</span>
171	          <Button variant="ghost" size="icon" className="h-7 w-7" onClick={prev} disabled={safeIndex === 0}>
172	            <ChevronLeft className="h-4 w-4" />
173	          </Button>
174	          <Button variant="ghost" size="icon" className="h-7 w-7" onClick={next} disabled={safeIndex === total - 1}>
175	            <ChevronRight className="h-4 w-4" />
176	          </Button>
177	        </div>
178	      </div>
179	
180	      {/* Task info */}
181	      <div className="flex items-start justify-between gap-4">
182	        <div className="flex flex-col gap-1.5 min-w-0">
183	          <div className="flex items-center gap-1.5 flex-wrap">
184	            <span className={`text-[10px] font-medium px-1.5 py-0.5 rounded border ${chipClass(item.type, item.category)}`}>
185	              {item.type === "eblast" ? "E-Blast" : (item.category ?? "Task")}
186	            </span>
187	          </div>
188	          <p className="text-lg font-semibold leading-tight">{item.name}</p>
189	          <p className="text-sm text-muted-foreground">
190	            {item.showName}
191	            <span className="mx-1.5 opacity-40">•</span>
192	            Due {formatDate(item.dueDate)}
193	          </p>
194	        </div>
195	
196	        <Link href={`/shows/${item.showId}?tab=${showTab}`} className="shrink-0">
197	          <Button variant="outline" size="sm">Open</Button>
198	        </Link>
199	      </div>
200	
201	      {/* Note — compact single line, expands on click */}
202	      {!isNoteOpen ? (
203	        <button
204	          onClick={openNote}
205	          className="flex items-center gap-1.5 w-full text-left text-sm text-muted-foreground hover:text-foreground transition-colors group"
206	        >
207	          <ChevronDown className="h-3.5 w-3.5 shrink-0 opacity-50 group-hover:opacity-80" />
208	          <span className="truncate">{currentNote || "Add a note…"}</span>
209	        </button>
210	      ) : (
211	        <div className="flex flex-col gap-1">
212	          <Textarea
213	            key={key}
214	            autoFocus
215	            value={currentNote}
216	            onChange={e => setNoteDrafts(p => ({ ...p, [key]: e.target.value }))}
217	            onBlur={closeNote}
218	            placeholder="Add a note…"
219	            className="resize-none text-sm min-h-[64px]"
220	            rows={2}
221	          />
222	          {savedFlash[key] && (
223	            <span className="text-xs text-muted-foreground">Saved</span>
224	          )}
225	        </div>
226	      )}
227	
228	      {/* Actions */}
229	      <div className="flex items-center justify-between gap-3">
230	        <Button
231	          variant="default"
232	          size="sm"
233	          className="gap-1.5"
234	          onClick={markComplete}
235	          disabled={isCompleting}
236	        >
237	          <Check className="h-3.5 w-3.5" />
238	          {completionLabel}
239	        </Button>
240	
241	        {/* Dot indicators */}
242	        {total > 1 && total <= 10 && (
243	          <div className="flex items-center gap-1">
244	            {items.map((_, i) => (
245	              <button
246	                key={i}
247	                onClick={() => setIndex(i)}
248	                className={`rounded-full transition-all ${
249	                  i === safeIndex
250	                    ? `h-1.5 w-4 ${isToday ? "bg-amber-400" : "bg-red-400"}`
251	                    : "h-1.5 w-1.5 bg-muted-foreground/30 hover:bg-muted-foreground/50"
252	                }`}
253	              />
254	            ))}
255	          </div>
256	        )}
257	      </div>
258	    </div>
259	  );
260	}
